INSERT INTO src_locator(source_work_id,source_artifact_id,locator_type,heading_path,display_citation) SELECT a.source_work_id,a.source_artifact_id,'heading','Space Combat > Special Considerations > Planetary Maneuvers',CASE w.work_code WHEN 'cepheus-engine.ogn' THEN 'Cepheus Engine SRD, Space Combat: Planetary Maneuvers' ELSE 'Cepheus Engine v9.1, Space Combat: Planetary Maneuvers' END FROM src_artifact a JOIN src_work w USING(source_work_id) WHERE (w.work_code='cepheus-engine.ogn' AND a.source_uri LIKE '%cepheus-engine-space-combat/') OR (w.work_code='cepheus-engine.github-v9.1' AND a.source_uri='src/book2/space-combat.md') ON CONFLICT DO NOTHING;
WITH p AS(SELECT content_package_id FROM sys_content_package WHERE package_code='cepheus-engine') INSERT INTO rule_rule(content_package_id,rule_code,name,rule_category,rule_status,description) SELECT content_package_id,'combat.space.planetary-maneuvers','Planetary Maneuvers','combat','approved','Orbital insertion and atmospheric entry with published world-profile modifiers and persistent vessel flight state.' FROM p;
CREATE TABLE rule_space_combat_planetary_maneuver(rule_id bigint NOT NULL REFERENCES rule_rule(rule_id),maneuver_code text NOT NULL CHECK(maneuver_code IN('orbital-insertion','atmospheric-entry')),action_name text NOT NULL,skill_rule_id bigint NOT NULL REFERENCES rule_skill(rule_id),difficulty_rule_id bigint NOT NULL REFERENCES rule_difficulty(rule_id),significant_action boolean NOT NULL,success_state text NOT NULL CHECK(success_state IN('orbit','atmosphere')),failure_state text NOT NULL CHECK(failure_state IN('decaying-orbit','orbit')),PRIMARY KEY(rule_id,maneuver_code));
INSERT INTO rule_space_combat_planetary_maneuver SELECT p.rule_id,v.code,v.name,s.rule_id,d.rule_id,true,v.success_state,v.failure_state FROM rule_rule p CROSS JOIN rule_rule s CROSS JOIN rule_rule d CROSS JOIN (VALUES('orbital-insertion','Orbital Insertion','orbit','decaying-orbit'),('atmospheric-entry','Atmospheric Entry','atmosphere','orbit')) v(code,name,success_state,failure_state) WHERE p.rule_code='combat.space.planetary-maneuvers' AND s.rule_code='skill.piloting' AND d.rule_code=CASE v.code WHEN 'orbital-insertion' THEN 'difficulty.routine' ELSE 'difficulty.average' END;
CREATE TABLE rule_space_combat_atmospheric_entry_modifier(rule_id bigint NOT NULL REFERENCES rule_rule(rule_id),modifier_code text NOT NULL,world_attribute text NOT NULL CHECK(world_attribute IN('size','atmosphere')),code_range int4range NOT NULL,modifier smallint,automatic_success boolean NOT NULL,display_order smallint NOT NULL,PRIMARY KEY(rule_id,modifier_code),CHECK((automatic_success AND modifier IS NULL) OR (NOT automatic_success AND modifier IS NOT NULL)));
INSERT INTO rule_space_combat_atmospheric_entry_modifier SELECT r.rule_id,v.* FROM rule_rule r CROSS JOIN (VALUES('size-large','size',int4range(9,NULL,'[)'),-2::smallint,false,1::smallint),('size-small','size',int4range(NULL,5,'[)'),2,false,2),('atmosphere-trace-or-none','atmosphere',int4range(NULL,2,'[)'),NULL,true,3),('atmosphere-thin','atmosphere',int4range(2,6,'[)'),2,false,4),('atmosphere-low','atmosphere',int4range(8,10,'[)'),-2,false,5),('atmosphere-dense','atmosphere',int4range(13,14,'[)'),-2,false,6),('atmosphere-ellipsoid','atmosphere',int4range(14,15,'[)'),2,false,7)) v(code,attribute,band,modifier,automatic_success,display_order) WHERE r.rule_code='combat.space.planetary-maneuvers';
INSERT INTO src_record_provenance(rule_id,content_package_id,source_locator_id,provenance_class,is_primary_citation) SELECT r.rule_id,r.content_package_id,l.source_locator_id,CASE w.work_code WHEN 'cepheus-engine.ogn' THEN 'direct' ELSE 'corroborating' END,w.work_code='cepheus-engine.ogn' FROM rule_rule r CROSS JOIN src_locator l JOIN src_work w USING(source_work_id) WHERE r.rule_code='combat.space.planetary-maneuvers' AND l.heading_path='Space Combat > Special Considerations > Planetary Maneuvers' AND w.work_code IN('cepheus-engine.ogn','cepheus-engine.github-v9.1');
INSERT INTO rule_space_combat_action(action_code,action_name,action_kind,crew_role,source_locator_id) SELECT v.code,v.name,'significant','pilot',l.source_locator_id FROM (VALUES('orbital-insertion','Orbital Insertion'),('atmospheric-entry','Atmospheric Entry')) v(code,name) CROSS JOIN LATERAL(SELECT source_locator_id FROM src_locator WHERE heading_path='Space Combat > Special Considerations > Planetary Maneuvers' ORDER BY source_locator_id LIMIT 1) l;

CREATE TABLE senc_vessel_planetary_state(senc_vessel_id bigint PRIMARY KEY,engagement_id bigint NOT NULL,campaign_id bigint NOT NULL,world_location_id bigint NOT NULL,flight_state text NOT NULL CHECK(flight_state IN('near-planet','orbit','decaying-orbit','atmosphere')),concurrency_version bigint NOT NULL DEFAULT 1 CHECK(concurrency_version>0),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(senc_vessel_id,engagement_id,campaign_id) REFERENCES senc_vessel(senc_vessel_id,engagement_id,campaign_id),FOREIGN KEY(world_location_id,campaign_id) REFERENCES loc_celestial_body(location_id,campaign_id));
CREATE TABLE senc_planetary_maneuver_receipt(planetary_maneuver_receipt_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,action_id bigint NOT NULL UNIQUE,space_combat_round_id bigint NOT NULL,engagement_id bigint NOT NULL,campaign_id bigint NOT NULL,senc_vessel_id bigint NOT NULL,pilot_assignment_id bigint NOT NULL,pilot_ship_id bigint NOT NULL,world_location_id bigint NOT NULL,world_profile_id bigint NOT NULL REFERENCES loc_world_profile(world_profile_id),maneuver_code text NOT NULL CHECK(maneuver_code IN('orbital-insertion','atmospheric-entry')),task_command_id bigint UNIQUE REFERENCES cmd_actor_task_receipt(command_id),size_code smallint NOT NULL,atmosphere_code smallint NOT NULL,world_modifier smallint NOT NULL,automatic_success boolean NOT NULL,task_succeeded boolean NOT NULL,state_before text NOT NULL,state_after text NOT NULL,state_version_before bigint NOT NULL,state_version_after bigint NOT NULL CHECK(state_version_after=state_version_before+1),recorded_at timestamptz NOT NULL DEFAULT clock_timestamp(),FOREIGN KEY(action_id,engagement_id,campaign_id) REFERENCES senc_action(space_combat_action_id,engagement_id,campaign_id),FOREIGN KEY(space_combat_round_id,engagement_id,campaign_id) REFERENCES senc_round(space_combat_round_id,engagement_id,campaign_id),FOREIGN KEY(senc_vessel_id,engagement_id,campaign_id) REFERENCES senc_vessel(senc_vessel_id,engagement_id,campaign_id),FOREIGN KEY(pilot_assignment_id,pilot_ship_id,campaign_id) REFERENCES ship_crew_assignment(crew_assignment_id,ship_id,campaign_id),FOREIGN KEY(world_location_id,campaign_id) REFERENCES loc_celestial_body(location_id,campaign_id),CHECK(automatic_success=(task_command_id IS NULL)));
CREATE FUNCTION senc_validate_planetary_maneuver() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE state senc_vessel_planetary_state%ROWTYPE;a record;profile loc_world_profile%ROWTYPE;task cmd_actor_task_receipt%ROWTYPE;expected_auto boolean;expected_modifier integer;expected_success boolean;expected_after text;pilot bigint;expected_difficulty bigint;BEGIN SELECT * INTO STRICT state FROM senc_vessel_planetary_state WHERE senc_vessel_id=NEW.senc_vessel_id FOR UPDATE;SELECT action.action_code,action.space_combat_round_id,turn.senc_vessel_id,turn.crew_assignment_id,assignment.ship_id,assignment.actor_id,assignment.duty_status INTO STRICT a FROM senc_action action JOIN senc_crew_turn turn USING(crew_turn_id) JOIN ship_crew_assignment assignment USING(crew_assignment_id) WHERE action.space_combat_action_id=NEW.action_id;SELECT * INTO STRICT profile FROM loc_world_profile WHERE world_profile_id=NEW.world_profile_id AND profile_status='current';SELECT rule_id INTO STRICT pilot FROM rule_rule WHERE rule_code='skill.piloting';SELECT difficulty_rule_id INTO STRICT expected_difficulty FROM rule_space_combat_planetary_maneuver m JOIN rule_rule r ON r.rule_id=m.rule_id WHERE r.rule_code='combat.space.planetary-maneuvers' AND maneuver_code=NEW.maneuver_code;
 expected_auto:=NEW.maneuver_code='atmospheric-entry' AND NEW.atmosphere_code<=1;SELECT coalesce(sum(modifier),0) INTO expected_modifier FROM rule_space_combat_atmospheric_entry_modifier m JOIN rule_rule r ON r.rule_id=m.rule_id WHERE r.rule_code='combat.space.planetary-maneuvers' AND NOT automatic_success AND ((world_attribute='size' AND code_range @> NEW.size_code) OR (world_attribute='atmosphere' AND code_range @> NEW.atmosphere_code));
 IF expected_auto THEN expected_success:=true;ELSE SELECT * INTO STRICT task FROM cmd_actor_task_receipt WHERE command_id=NEW.task_command_id;expected_success:=task.succeeded;END IF;expected_after:=CASE NEW.maneuver_code WHEN 'orbital-insertion' THEN CASE WHEN expected_success THEN 'orbit' ELSE 'decaying-orbit' END ELSE CASE WHEN expected_success THEN 'atmosphere' ELSE 'orbit' END END;
 IF a.action_code<>NEW.maneuver_code OR a.space_combat_round_id<>NEW.space_combat_round_id OR a.senc_vessel_id<>NEW.senc_vessel_id OR a.crew_assignment_id<>NEW.pilot_assignment_id OR a.ship_id<>NEW.pilot_ship_id OR a.duty_status<>'active' OR state.engagement_id<>NEW.engagement_id OR state.campaign_id<>NEW.campaign_id OR state.world_location_id<>NEW.world_location_id OR state.flight_state<>NEW.state_before OR state.concurrency_version<>NEW.state_version_before OR profile.location_id<>NEW.world_location_id OR profile.campaign_id<>NEW.campaign_id OR profile.size_code<>NEW.size_code OR profile.atmosphere_code<>NEW.atmosphere_code OR NEW.world_modifier<>(CASE WHEN NEW.maneuver_code='atmospheric-entry' THEN expected_modifier ELSE 0 END) OR NEW.automatic_success<>expected_auto OR NEW.task_succeeded<>expected_success OR NEW.state_after<>expected_after OR (NEW.maneuver_code='orbital-insertion' AND state.flight_state<>'near-planet') OR (NEW.maneuver_code='atmospheric-entry' AND state.flight_state<>'orbit')
  OR (NOT expected_auto AND (task.actor_id<>a.actor_id OR task.skill_rule_id<>pilot OR task.difficulty_rule_id<>expected_difficulty OR task.circumstance_modifier<>(CASE WHEN NEW.maneuver_code='atmospheric-entry' THEN expected_modifier ELSE 0 END))) THEN RAISE EXCEPTION 'Planetary maneuver fails active Pilot, current world profile, published modifier, task, or flight-state recomputation' USING ERRCODE='23514';END IF;
 UPDATE senc_vessel_planetary_state SET flight_state=expected_after,concurrency_version=state.concurrency_version+1,updated_at=clock_timestamp() WHERE senc_vessel_id=state.senc_vessel_id;RETURN NEW;END $$;
CREATE TRIGGER senc_planetary_maneuver_valid BEFORE INSERT ON senc_planetary_maneuver_receipt FOR EACH ROW EXECUTE FUNCTION senc_validate_planetary_maneuver();
CREATE FUNCTION senc_reject_planetary_maneuver_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Planetary maneuver receipts are immutable';END $$;CREATE TRIGGER senc_planetary_maneuver_immutable BEFORE UPDATE OR DELETE ON senc_planetary_maneuver_receipt FOR EACH ROW EXECUTE FUNCTION senc_reject_planetary_maneuver_mutation();
